#!/usr/bin/env node
/**
 * Bring a generated doc's translated pair back into structural agreement.
 *
 * Used for docs whose English side is written by a generator (`Generated by
 * scripts/...`) while the `.zh.md` side is a hand-maintained translation the
 * generator never touches. Renaming packages perturbs those docs in two ways the
 * codemod cannot follow:
 *
 *  1. The generator sorts sections by package name, so renaming
 *     `subagent-dsh-sdk` -> `subagent-avn-sdk` moves it ahead of
 *     `subagent-claude-code` and every later section shifts.
 *  2. The generator derives anchors from the package name by stripping `@` and
 *     the first `/` (`@aeven/bash-local` -> `aevenbash-local`), which no token
 *     substitution can reproduce.
 *
 * This tool reorders the translated sections into the English order, adopts the
 * English anchor ids, copies each English code block verbatim (the pairing gate
 * requires code fences to be byte-identical across a pair), and rewrites
 * in-document links to the adopted anchors. Translated prose is left alone.
 *
 * Usage:
 *   node scripts/sync-generated-doc-pair.mjs <english.md> <translated.md> [--dry-run]
 *
 * @module scripts/sync-generated-doc-pair
 */

import { readFileSync, writeFileSync } from 'node:fs'

/** Package heading, e.g. "## `@aeven/acp`". Language-neutral, so it identifies a section. */
const HEADING = /^## `(@[a-z0-9/-]+)`\s*$/m
/** Generated anchor line, e.g. `<a id="aevenacp"></a>`. */
const ANCHOR = /^<a id="[^"]*"><\/a>\s*$/m

/**
 * Split a document into its preamble and anchor-delimited sections.
 * @param text - file contents.
 * @returns the preamble plus a map of package name to section text.
 */
function sections(text) {
  const parts = text.split(/(?=^<a id=)/m)
  const preamble = parts[0] ?? ''
  const byName = new Map()
  for (const part of parts.slice(1)) {
    const heading = HEADING.exec(part)
    if (heading !== null) byName.set(heading[1], part)
  }
  return { preamble, byName }
}

/**
 * @param text - a section's text.
 * @returns the fenced code blocks it contains, in order.
 */
function codeBlocks(text) {
  return text.match(/^```[^\n]*\n[\s\S]*?\n```\s*$/gm) ?? []
}

/**
 * @param text - a section's text.
 * @returns its anchor id, or undefined.
 */
function anchorId(text) {
  const m = /^<a id="([^"]*)"><\/a>/m.exec(text)
  return m?.[1]
}

/**
 * Splice the English code blocks into a translated section, positionally and in
 * order, leaving every other line untouched.
 * @param translated - the translated section text.
 * @param english - the corresponding English section text.
 * @returns the section with English code blocks.
 */
function adoptCodeBlocks(translated, english) {
  const source = codeBlocks(english)
  let index = 0
  return translated.replace(/^```[^\n]*\n[\s\S]*?\n```\s*$/gm, (original) => {
    const next = source[index]
    index += 1
    return next === undefined ? original : `${next}\n`
  })
}

function main() {
  const [englishPath, translatedPath] = process.argv.slice(2).filter((a) => !a.startsWith('--'))
  const dryRun = process.argv.includes('--dry-run')
  if (englishPath === undefined || translatedPath === undefined) {
    console.error('usage: sync-generated-doc-pair.mjs <english.md> <translated.md> [--dry-run]')
    process.exit(2)
  }

  const english = readFileSync(englishPath, 'utf8')
  const translated = readFileSync(translatedPath, 'utf8')
  const en = sections(english)
  const zh = sections(translated)

  const order = [...en.byName.keys()]
  const missing = order.filter((name) => !zh.byName.has(name))
  const extra = [...zh.byName.keys()].filter((name) => !en.byName.has(name))
  if (missing.length > 0 || extra.length > 0) {
    console.error(`sync-generated-doc-pair: section sets differ (missing ${missing.length}, extra ${extra.length})`)
    for (const n of [...missing, ...extra].slice(0, 10)) console.error(`  ${n}`)
    process.exit(1)
  }

  // Adopt the English anchor for each section, remembering the translation's own
  // anchor so in-document links can be repointed.
  const linkMap = new Map()
  const rendered = []
  for (const name of order) {
    const enSection = en.byName.get(name)
    let zhSection = zh.byName.get(name)
    const zhAnchor = anchorId(zhSection)
    const enAnchor = anchorId(enSection)
    if (zhAnchor !== undefined && enAnchor !== undefined && zhAnchor !== enAnchor) {
      linkMap.set(zhAnchor, enAnchor)
      zhSection = zhSection.replace(ANCHOR, `<a id="${enAnchor}"></a>`)
    }
    rendered.push(adoptCodeBlocks(zhSection, enSection))
  }

  let out = zh.preamble + rendered.join('')
  let linkFixes = 0
  for (const [from, to] of linkMap) {
    const pattern = new RegExp(`\\]\\(#${from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\)`, 'g')
    out = out.replace(pattern, () => { linkFixes += 1; return `](#${to})` })
  }

  const changed = out !== translated
  console.log(
    `sync-generated-doc-pair: ${order.length} sections, ${linkMap.size} anchors adopted, `
    + `${linkFixes} links repointed, ${changed ? 'CHANGED' : 'already in sync'}`,
  )
  if (changed && !dryRun) writeFileSync(translatedPath, out)
}

main()
